import { Scene, Circle, Rect, Mask, ZoomView, Color, Vec3 } from "retiam";

const scene = new Scene({ canvas });

// 1. Stencil Masking: Clip a colorful grid inside a circular aperture
const aperture = new Circle(3.0);
const content = new Rect(8.0, 8.0, { fill: Color.fromHex("#3b82f6") });

const maskedAvatar = new Mask(aperture, content);
scene.add(maskedAvatar);

// 2. Zoom Callout: Magnify the center of the avatar
const callout = new ZoomView(maskedAvatar, {
    zoom: 2.5,
    windowRadius: 2.0,
    windowPosition: new Vec3(5, 2, 0),
    borderColor: Color.WHITE,
    borderWidth: 0.08,
    showConnector: true
});
scene.add(callout);
